INSERT INTO `cursos` (`id`, `nome`, `desc_rapida`, `desc_longa`, `valor`, `professor`, `categoria`, `imagem`, `status`, `carga`, `mensagem`, `arquivo`, `ano`, `palavras`, `grupo`, `nome_url`, `pacote`, `sistema`, `link`, `tecnologias`, `promocao`, `matriculas`, `comissao`, `is_matricula`, `split`, `conteudo`) VALUES
(26, 'Agronegócios', '', '<div>Instituição: UNICORP Cursos e SESTED Cursos</div><div>&nbsp;Curso: Técnico em Agronegócio. - Eixo Tecnológico: Recursos Naturais</div><div style= text-align:  center;=  ><b>PLANO DE CURSO</b></div><div>Habilitação: Profissional de Técnico de Nível Médio em Agronegócios. Classificação Brasileira de Ocupações (CBO): 3211-05</div><div>Carga Horária: 1.180 horas (Compostas dos Módulos I a V) Estágio: 240 horas</div><div style= text-align:  center;=  ><b>DESCRIÇÃO</b></div><div>O curso técnico em agronegócios é projetado para fornecer aos estudantes conhecimentos práticos e habilidades relevantes para a gestão de atividades relacionadas ao setor agrícola e agroindustrial. Esse tipo de curso é voltado para preparar profissionais que possam atuar tanto na produção agrícola quanto nas etapas subsequentes da cadeia produtiva, incluindo distribuição, comercialização e processamento de produtos agrícolas.</div><div style= text-align:  center;=  ><br></div><div style= text-align:  center;=  ><b>MATRIZ CURRICULAR</b></div><div><b>MÓDULO I - TÉCNICO EM AGRONEGÓCIOS.</b>&nbsp;</div><div>- INTRODUÇÃO AO EAD - 20 horas&nbsp;</div><div>- GESTÃO DE RECURSOS HUMANOS&nbsp; - 40 horas</div><div>&nbsp;- MATEMÁTICA FINANCEIRA 40 horas</div><div>- FUNDAMENTOS DA ADMINISTRAÇÃO 40 horas</div><div>- EMPREENDEDORISMO 40 horas</div><div>ADMINISTRAÇÃO DE PESSOAL 20 horas</div><div>GESTÃO DA QUALIDADE 20 horas</div><div>PLANEJAMENTO ESTRATÉGICO 20 horas</div><div>TEORIAS DA ADMINISTRAÇÃO 20 horas</div><div>GEOPROCESSAMENTO&nbsp; - 40 horas</div><div>MICROBIOLOGIA DOS ALIMENTOS - 60 horas</div><div><br></div><div><b>MÓDULO II - TÉCNICO EM AGRONEGÓCIOS.</b></div><div>QUÍMICA GERAL E INORGÂNICA - 60 horas</div><div>GESTÃO DA CADEIA DE SUPRIMENTOS - 20 horas</div><div>ESTUDO DE MARKETING SUSTENTÁVEL&nbsp; - 40 horas</div><div>GERENCIAMENTO DOS ASPECTOS E IMPACTOS AMBIENTAIS&nbsp; - 40 horas</div><div><br></div><div><div><b>MÓDULO III - TÉCNICO EM AGRONEGÓCIOS.&nbsp;</b></div><div>DIREITO AMBIENTAL 20 horas</div><div>BIOQUÍMICA DOS ALIMENTOS&nbsp; - 40 horas</div><div>GESTÃO DE TRANSPORTES&nbsp; - 40 horas</div><div>ECONOMIA E MERCADO GLOBAL - 20 horas</div><div><br></div><div><b>MÓDULO IV - TÉCNICO EM AGRONEGÓCIOS.&nbsp;</b></div><div>DIREITO APLICADO AO AGRONEGÓCIO - 40 horas</div><div>AGRONOMIA E AGRONEGÓCIO - 40 horas</div><div>40 ECOLOGIA E LIMNOLOGIA 60</div><div>CLIMATOLOGIA E METEOROLOGIA AGRÍCOLA&nbsp; - 40 horas</div><div>HIDROLOGIA - 20 horas</div><div>TECNOLOGIA E INOVAÇÃO APLICADAS A AGRONEGÓCIOS&nbsp; - 40 horas</div><div><br></div><div><b>MÓDULO V - TÉCNICO EM AGRONEGÓCIOS.</b></div><div>GESTÃO EMPRESARIAL RURAL - 40 horas</div><div>GOVERNANÇA CORPORATIVA, CONTROLE INTERNO E COMPLIANCE - 20 horas</div><div>20 MERCADO DO AGRONEGÓCIO 60</div><div>LOGÍSTICA DE AMRMAZENAGEM&nbsp; - 40 horas</div><div>LOGÍSTICA DE TRANSPORTE&nbsp; - 40 horas</div><div>PORTUGUÊS INSTRUMENTAL - 20 horas</div><div>FUNDAMENTOS EXTENSÃO RURAL - 20 horas</div><div>ORIENTAÇÕES DO ESTÁGIO SUPERVISIONADO - 240 horas</div></div>', 4900.00, 195, 21, '07-11-2025-11-00-14-01-08-2025-15-29-34-Agronegвcios.jpg', 'Aprovado', 1200, NULL, NULL, 2025, '', 7, 'agronegocios', NULL, 0, NULL, 0, 0.00, 0, 0, 0, 1, NULL),
